        'tracksadm.l_dumps':         'Eigene Ablagen je Benutzer (1–100)',
        'tracksadm.l_dumps_hint':    'Notbremse gegen versehentliches Anlegen in Serie. Globale Ablagen sind davon nicht betroffen (Grenze dort: 30).',
