// ─── Core ──────────────────────────────────────────────────────────────────

window._lang = localStorage.getItem('jarvis_lang') || 'de';

/** Gibt den übersetzten String zurück (Fallback: Deutsch, dann Key selbst). */
window.t = function(key) {
    return (_I18N[window._lang] && _I18N[window._lang][key])
        || (_I18N.de[key])
        || key;
};

/** Wendet alle data-i18n-Attribute auf das Dokument an. */
window.applyLang = function() {
    // Sprach-Attribut fuer CSS-Sprachbloecke (.i18n-de / .i18n-en):
    // html[data-lang="en"] blendet .i18n-de aus und umgekehrt. Wird fuer
    // lange Fliesstext-Inhalte (z.B. API-Dokumentation) statt Einzel-Keys genutzt.
    document.documentElement.setAttribute('data-lang', window._lang);
    // Textinhalt
    document.querySelectorAll('[data-i18n]').forEach(el => {
        el.textContent = window.t(el.dataset.i18n);
    });
    // Placeholder
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        el.placeholder = window.t(el.dataset.i18nPlaceholder);
    });
    // title-Attribut
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        el.title = window.t(el.dataset.i18nTitle);
    });
    // aria-label
    document.querySelectorAll('[data-i18n-aria]').forEach(el => {
        el.setAttribute('aria-label', window.t(el.dataset.i18nAria));
    });
    // Vorschlag, den TAB uebernimmt (frontend/js/tabfill.js). Noetig, wo der
    // Platzhalter eine AUFZAEHLUNG ist ("z. B. Signatur, Anrede-Form, …") und
    // als Feldinhalt keinen Sinn ergaebe – dann steht der uebernehmbare Text
    // getrennt daneben und muss ebenfalls uebersetzt werden.
    document.querySelectorAll('[data-i18n-tabfill]').forEach(el => {
        el.setAttribute('data-tabfill', window.t(el.dataset.i18nTabfill));
    });
    // HTML-Inhalt (für Elemente mit eingebetteten Tags wie <code>, <strong>)
    document.querySelectorAll('[data-i18n-html]').forEach(el => {
        el.innerHTML = window.t(el.dataset.i18nHtml);
    });

    // Task-Input Placeholder (wird von app.js dynamisch gesetzt – überschreiben)
    const taskInput = document.getElementById('task-input');
    if (taskInput && !taskInput.dataset.agentActive) {
        taskInput.placeholder = window.t('input.placeholder');
    }

    // Browser-Formularvalidierung übersetzen (alle required-Inputs)
    document.querySelectorAll('input[required]').forEach(input => {
        input.addEventListener('invalid', _onInvalid, { once: false });
        input.addEventListener('input',   _onInput,   { once: false });
    });

    // Sprachschalter-Buttons synchronisieren
    document.querySelectorAll('.lang-toggle-btn').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.lang === window._lang);
    });
    // Signal fuer Inhalte, die NICHT ueber data-i18n laufen: serverseitig
    // uebersetzte Listen (z.B. der SAP-Analysekatalog) und alles, was ein
    // Modul selbst zusammenbaut. applyLang() erreicht die nicht – ohne dieses
    // Ereignis muesste jede Seite window.setLang umschreiben, um mitzubekommen,
    // dass sich die Sprache geaendert hat. Zuhoerer sind freiwillig; Seiten
    // ohne Listener merken nichts davon.
    try {
        window.dispatchEvent(new CustomEvent('jarvis-lang-changed',
                                             { detail: { lang: window._lang } }));
    } catch (e) { /* aeltere Browser ohne CustomEvent-Konstruktor */ }
};

function _onInvalid(e) {
    e.target.setCustomValidity(window.t('validation.required'));
}
function _onInput(e) {
    e.target.setCustomValidity('');
}

/** Wechselt die Sprache und speichert sie in localStorage. */
window.setLang = function(lang) {
    if (!_I18N[lang]) return;
    window._lang = lang;
    localStorage.setItem('jarvis_lang', lang);
    window.applyLang();
};

// ─── Auto-Apply nach DOM-Ready ─────────────────────────────────────────────

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', window.applyLang);
} else {
    window.applyLang();
}
